public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns reactions added for a message, along with their sender
    /// </summary>
    public Task<TdLib.TdApi.Objects.AddedReactions> GetMessageAddedReactionsAsync(long chatId = default, long messageId = default, ReactionType reactionType = default, string offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("GetMessageAddedReactionsAsync", typeof(GetMessageAddedReactions).FullName ?? "GetMessageAddedReactionsAsync");

           try
           {
             return client.GetMessageAddedReactionsAsync(chatId, messageId, reactionType, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
